import * as net from 'node:net';
function main(): void {
  let got = '';
  const server: any = net.createServer((sock: any): void => {
    sock.on('data', (d: any): void => { got += d.toString(); });
    sock.on('close', (): void => { server.close(); });
  });
  server.on('close', (): void => { console.log('server got', JSON.stringify(got)); });
  server.listen(0, '127.0.0.1', (): void => {
    const port = server.address().port;
    const c: any = net.connect(port, '127.0.0.1', (): void => { c.write('ping'); c.destroy(); });
  });
}
